 CREATE OR REPLACE FUNCTION public.getroleprofile(userid character varying)                                                                                                                                                 
  RETURNS TABLE(roleid integer, rolename character varying, description character varying, id uuid, module character varying, task character varying, action text, resourcetype integer, resourcetypedesc character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                          
 AS $function$                                                                                                                                                                                                            
                                                                                                                                                                                                                          
 BEGIN                                                                                                                                                                                                                    
                                                                                                                                                                                                                          
     RETURN QUERY                                                                                                                                                                                                         
                                                                                                                                                                                                                          
                                                                                                                                                                                                                          
 SELECT r.id roleid, r.name as rolename, r.description as "role", res.id, res.resourcename module, '' as task, '' as action                                                                                               
 , rt.id as resourcetype, rt.resourcetypedesc as resourcetypedesc                                                                                                                                                         
 FROM rolemapping rm                                                                                                                                                                                                      
 INNER JOIN role_resource rr ON rr.roleid = rm.roleid AND rm.principaltype = 'USER'                                                                                                                                       
 INNER JOIN role r ON rr.roleid = r.id                                                                                                                                                                                    
 INNER JOIN resource res ON rr.resourceid = res.id                                                                                                                                                                        
 INNER JOIN resourcetype rt ON res.resourcetype = rt.id                                                                                                                                                                   
 WHERE res.resourcetype = 1 AND rm.principalid = userid AND rr.isallowed = true                                                                                                                                           
 Union All                                                                                                                                                                                                                
 SELECT r.id roleid, r.name as rolename, r.description as "role", res.id, res1.resourcename as module, res.resourcename as task, '' as action                                                                             
 , rt.id as resourcetype, rt.resourcetypedesc as resourcetypedesc                                                                                                                                                         
 FROM rolemapping rm                                                                                                                                                                                                      
 INNER JOIN role_resource rr ON rr.roleid = rm.roleid AND rm.principaltype = 'USER'                                                                                                                                       
 INNER JOIN role r ON rr.roleid = r.id                                                                                                                                                                                    
 INNER JOIN resource res ON rr.resourceid = res.id                                                                                                                                                                        
 INNER JOIN resourcetype rt ON res.resourcetype = rt.id                                                                                                                                                                   
 LEFT JOIN resource res1 ON res1.id = res.parentid AND res1.resourcetype = 1                                                                                                                                              
 WHERE res.resourcetype = 2 AND rm.principalid = userid AND rr.isallowed = true                                                                                                                                           
 Union All                                                                                                                                                                                                                
 SELECT r.id roleid, r.name as rolename, r.description as "role", res.id, res1.resourcename as module, '' as task, res.resourcename as action                                                                             
 , rt.id as resourcetype, rt.resourcetypedesc as resourcetypedesc                                                                                                                                                         
 FROM rolemapping rm                                                                                                                                                                                                      
 INNER JOIN role_resource rr ON rr.roleid = rm.roleid AND rm.principaltype = 'USER'                                                                                                                                       
 INNER JOIN role r ON rr.roleid = r.id                                                                                                                                                                                    
 INNER JOIN resource res ON rr.resourceid = res.id                                                                                                                                                                        
 INNER JOIN resourcetype rt ON res.resourcetype = rt.id                                                                                                                                                                   
 INNER JOIN resource res1 ON res1.id = res.parentid AND res1.resourcetype = 1                                                                                                                                             
 WHERE res.resourcetype = 3 AND rm.principalid = userid AND rr.isallowed = true;                                                                                                                                          
   END;                                                                                                                                                                                                                   
 $function$                                                                                                                                                                                                                 

